import{_ as p,a0 as l,w as a,s as d,I as o,x as s,a1 as r,A as i,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 中像专业人士一样使用 GNOME 截图工具 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中像专业人士一样使用 GNOME 截图工具 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中像专业人士一样使用 GNOME 截图工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中像专业人士一样使用 GNOME 截图工具 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220101 Using GNOME Screenshot Tool in Linux Like a Pro","title":"在 Linux 中像专业人士一样使用 GNOME 截图工具","tag":"202201","desc":""},"relativePath":"202201/20220101 Using GNOME Screenshot Tool in Linux Like a Pro.md","filePath":"[post].md"}'),m={name:"202201/20220101 Using GNOME Screenshot Tool in Linux Like a Pro.md"};function f(u,t,h,g,S,x){const e=l("Link");return a(),d("div",null,[t[26]||(t[26]=o("h1",{id:"在-linux-中像专业人士一样使用-gnome-截图工具",tabindex:"-1"},[s("在 Linux 中像专业人士一样使用 GNOME 截图工具 "),o("a",{class:"header-anchor",href:"#在-linux-中像专业人士一样使用-gnome-截图工具","aria-label":"Permalink to “在 Linux 中像专业人士一样使用 GNOME 截图工具”"},"​")],-1)),o("p",null,[t[2]||(t[2]=s("有 ",-1)),r(e,{href:"https://itsfoss.com/take-screenshot-linux/"},{default:i(()=>[...t[0]||(t[0]=[s("几个可用于 Linux 的截图工具",-1)])]),_:1}),t[3]||(t[3]=s("，我喜欢 ",-1)),r(e,{href:"https://itsfoss.com/flameshot/"},{default:i(()=>[...t[1]||(t[1]=[s("使用 Flameshot 进行截图",-1)])]),_:1}),t[4]||(t[4]=s(" 和 Shutter 来编辑现有的截图。",-1))]),t[27]||(t[27]=o("p",null,"但不幸的是，Flameshot 不能在 4K 屏幕上工作。因此，我不得不使用默认的 GNOME 截图工具，它在我的带有超高清屏幕的戴尔 XPS 上工作得非常好。",-1)),t[28]||(t[28]=o("p",null,[o("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/gnome-screenshot-tool.jpg?resize=800%2C413&ssl=1",alt:"GNOME screenshot tool"})],-1)),o("p",null,[t[6]||(t[6]=s("这一“被迫之举”让我意识到，如果你知道如何正确使用，",-1)),r(e,{href:"https://apps.gnome.org/app/org.gnome.Screenshot/"},{default:i(()=>[...t[5]||(t[5]=[s("GNOME 截图",-1)])]),_:1}),t[7]||(t[7]=s(" 并不是一个糟糕的工具。",-1))]),t[29]||(t[29]=n('<p>在这里，我指的是用键盘快捷键来使用它，因为这样可以节省大量的时间。</p><p>让我展示一下如何像专家一样用那些方便的键盘快捷键来使用 GNOME 截图应用。</p><p>我假定你没有改变这里的默认的截图的键盘快捷键。</p><h3 id="对整个屏幕进行截图-使用-prt-scr-键" tabindex="-1">对整个屏幕进行截图：使用 Prt Scr 键 <a class="header-anchor" href="#对整个屏幕进行截图-使用-prt-scr-键" aria-label="Permalink to “对整个屏幕进行截图：使用 Prt Scr 键”">​</a></h3><p>这是最简单的操作。在你的键盘上找到 <code>Prt Sc</code>（或称 <code>Prt Scr</code>、<code>Prt Scn</code>）键并按下它。它将对整个屏幕进行截图，并将其保存在你的主目录下的图片文件夹中。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/screenshot-of-entire-screen-gnome.jpg?resize=800%2C532&amp;ssl=1" alt="Screenshot of entire screen saved as PNG file"></p><p>在某些发行版（或版本）中，你可能会看到是否要保存截图的选项，但大多数情况下，它会自动保存屏幕截图。</p><p>这里需要注意的另一件事是，如果你有多个屏幕连接到系统上，它会把所有的屏幕一起截图。这意味着，你会得到一个超宽的图像。</p><p>但是，如果你只想对某个应用进行截图，而不是对整个屏幕进行截图呢？</p><h3 id="给一个应用程序的窗口截图-使用-alt-prt-scr-键" tabindex="-1">给一个应用程序的窗口截图：使用 Alt+Prt Scr 键 <a class="header-anchor" href="#给一个应用程序的窗口截图-使用-alt-prt-scr-键" aria-label="Permalink to “给一个应用程序的窗口截图：使用 Alt+Prt Scr 键”">​</a></h3><p>要给正在运行的图形应用截图，你需要这样做：</p><p>点击正在运行的应用，使其获得焦点。现在，按住 <code>Alt</code> 键并按 <code>Prt Scr</code> 键。</p><p>它将得到应用窗口的截图，并保存到图片目录中。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/screenshot-of-an-application-windows-gnome.png?resize=800%2C437&amp;ssl=1" alt="Screenshot of an application window in GNOME"></p><p>这样获取的截图也有一个阴影效果，看起来很不错。</p><p>这很好，但如果你只想给某个特定区域截图，而不是整个屏幕呢？这也有一个技巧。</p><h3 id="对屏幕的选定区域进行截图-使用-shift-prt-scr-键" tabindex="-1">对屏幕的选定区域进行截图：使用 Shift+Prt Scr 键 <a class="header-anchor" href="#对屏幕的选定区域进行截图-使用-shift-prt-scr-键" aria-label="Permalink to “对屏幕的选定区域进行截图：使用 Shift+Prt Scr 键”">​</a></h3><p>按住 <code>Shift</code> 键。然后按 <code>Prt Scr</code> 键。你会看到屏幕上出现一个选框。将鼠标移动到所需的区域，开始拖动光标。它将高亮显示该区域，并在你释放鼠标后立即进行截图。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/take-screenshot-of-region-gnome.webp?resize=800%2C430&amp;ssl=1" alt="Taking screenshot of an area in GNOME"></p><h3 id="复制截图到剪贴板而不是保存它们" tabindex="-1">复制截图到剪贴板而不是保存它们 <a class="header-anchor" href="#复制截图到剪贴板而不是保存它们" aria-label="Permalink to “复制截图到剪贴板而不是保存它们”">​</a></h3><p>当你在和别人聊天时，要和对方分享屏幕截图时，这非常有用。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/saving-screenshot-to-clipboard-and-using-it.webp?resize=800%2C476&amp;ssl=1" alt="Screenshot copied to the clipboard can be used in various applications"></p><p>首先截图，但没必要将保存的截图文件附在聊天工具中。相反，你可以直接将截图复制到剪贴板，然后使用 <code>Ctrl+V</code> 快捷键将图像（从剪贴板）粘贴到聊天工具。</p><p>这样，你的系统就不会保留不必要的截图，你也可以节省一些鼠标点击次数。</p><p>要把截图保存到剪贴板，以便你能把它们粘贴到聊天工具、绘图工具或文档中，你必须把 <code>Ctrl</code> 键和你在前面几节中看到的其他截图快捷键一起使用。</p><ul><li><code>Ctrl+Prt Scr</code>：将整个屏幕的截图复制到剪贴板上。</li><li><code>Ctrl+Alt+Prt Scr</code>：将应用窗口的截图复制到剪贴板上。</li><li><code>Ctrl+Shift+Prt Scr</code>：将选定区域的截图复制到剪贴板上</li></ul>',26)),o("p",null,[t[9]||(t[9]=s("我必须补充一点，在这种情况下，",-1)),r(e,{href:"https://itsfoss.com/flameshot/"},{default:i(()=>[...t[8]||(t[8]=[s("使用像 Flameshot 这样的工具",-1)])]),_:1}),t[10]||(t[10]=s(" 甚至更好一些，因为它允许你在将截图保存到剪贴板之前对其进行注释。这样，你可以很容易地高亮屏幕的重要部分。",-1))]),t[30]||(t[30]=n('<h3 id="在截图中添加延迟-以便对下拉菜单进行截图" tabindex="-1">在截图中添加延迟，以便对下拉菜单进行截图 <a class="header-anchor" href="#在截图中添加延迟-以便对下拉菜单进行截图" aria-label="Permalink to “在截图中添加延迟，以便对下拉菜单进行截图”">​</a></h3><p>到目前为止，一切都很好。你只需按下几个键，就可以随心所欲地进行截图了。</p><p>问题是，当你要对下拉菜单或右键动作等进行截图时。当你按下屏幕截图键时，想要的项目可能会消失。</p><p>为了处理这种情况，你可以对该区域或整个屏幕进行截图，但要有一个延迟。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/taking-screenshot-with-delay-gnome.webp?resize=800%2C428&amp;ssl=1" alt="Taking screenshot with delay"></p><p>在 GNOME 屏幕截图工具中，你可以选择添加这个延迟。例如，你添加了 6 秒的延迟。你点击截图按钮，有 6 秒时间来做/显示你想做的事情。6 秒后，它就会自动截图了。</p><h3 id="你有什么技巧吗" tabindex="-1">你有什么技巧吗？ <a class="header-anchor" href="#你有什么技巧吗" aria-label="Permalink to “你有什么技巧吗？”">​</a></h3><p>这就是我使用 GNOME 截图工具的所有技巧。如果你还没有广泛地使用它，你应该会发现它很有帮助。如果你已经是一个专家，也许你知道一些可以添加到本文中的东西？请在评论区与我们其他人分享吧。</p><hr>',9)),o("p",null,[t[12]||(t[12]=s("via: ",-1)),r(e,{href:"https://itsfoss.com/using-gnome-screenshot-tool/"},{default:i(()=>[...t[11]||(t[11]=[s("https://itsfoss.com/using-gnome-screenshot-tool/",-1)])]),_:1})]),o("p",null,[t[17]||(t[17]=s("作者：",-1)),r(e,{href:"https://itsfoss.com/author/abhishek/"},{default:i(()=>[...t[13]||(t[13]=[s("Abhishek Prakash",-1)])]),_:1}),t[18]||(t[18]=s(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[14]||(t[14]=[s("lujun9972",-1)])]),_:1}),t[19]||(t[19]=s(" 译者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:i(()=>[...t[15]||(t[15]=[s("geekpi",-1)])]),_:1}),t[20]||(t[20]=s(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[16]||(t[16]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[23]||(t[23]=s("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[21]||(t[21]=[s("LCTT",-1)])]),_:1}),t[24]||(t[24]=s(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...t[22]||(t[22]=[s("Linux中国",-1)])]),_:1}),t[25]||(t[25]=s(" 荣誉推出",-1))])])}const N=p(m,[["render",f]]);export{C as __pageData,N as default};
